-- 23.11.2026 — Yıl başı toplu online eğitim (4 saat yenileme / 8 saat temel) — canlıya yüklemeden ÖNCE phpMyAdmin'de çalıştırın.
ALTER TABLE `egitim_paketleri` ADD COLUMN IF NOT EXISTS `egitim_turu` VARCHAR(20) NOT NULL DEFAULT 'ilk_defa' AFTER `ad`;
ALTER TABLE `egitim_atamalari` ADD INDEX IF NOT EXISTS `egitim_atamalari_paket_index` (`egitim_paketi_id`);
ALTER TABLE `egitim_atamalari` DROP INDEX IF EXISTS `egitim_atamalari_egitim_paketi_id_calisan_id_unique`;
ALTER TABLE `egitim_atamalari` ADD COLUMN IF NOT EXISTS `donem_yili` SMALLINT UNSIGNED NULL AFTER `egitim_turu`;
ALTER TABLE `uzaktan_egitim_firma_ayarlari` ADD COLUMN IF NOT EXISTS `icerik_onaylari` LONGTEXT NULL;
CREATE TABLE IF NOT EXISTS `egitim_toplu_bildirimleri` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `user_id` BIGINT UNSIGNED NOT NULL, `firma_id` BIGINT UNSIGNED NOT NULL, `yil` SMALLINT UNSIGNED NOT NULL, `yenileme_sayisi` INT UNSIGNED NOT NULL DEFAULT 0, `ilk_defa_sayisi` INT UNSIGNED NOT NULL DEFAULT 0, `eposta` VARCHAR(255) NULL, `eposta_gonderildi_at` TIMESTAMP NULL, `eposta_hatasi` TEXT NULL, `created_at` TIMESTAMP NULL, `updated_at` TIMESTAMP NULL, PRIMARY KEY (`id`), UNIQUE KEY `egitim_toplu_bildirimleri_firma_id_yil_unique` (`firma_id`, `yil`), KEY `egitim_toplu_bildirimleri_user_id_foreign` (`user_id`), CONSTRAINT `egitim_toplu_bildirimleri_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `egitim_toplu_bildirimleri_firma_id_foreign` FOREIGN KEY (`firma_id`) REFERENCES `firmalar` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `migrations` (`migration`,`batch`) SELECT '2026_11_23_100000_uzaktan_egitim_yillik_yenileme', (SELECT COALESCE(MAX(`batch`),0)+1 FROM `migrations`) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `migrations` WHERE `migration`='2026_11_23_100000_uzaktan_egitim_yillik_yenileme');
-- Doğrulama: egitim_turu, donem_yili, icerik_onaylari sütunları ve yeni tablo görünmeli.
SELECT (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND ((TABLE_NAME='egitim_paketleri' AND COLUMN_NAME='egitim_turu') OR (TABLE_NAME='egitim_atamalari' AND COLUMN_NAME='donem_yili') OR (TABLE_NAME='uzaktan_egitim_firma_ayarlari' AND COLUMN_NAME='icerik_onaylari'))) AS yeni_sutun_3_olmali, (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME='egitim_toplu_bildirimleri') AS yeni_tablo_1_olmali;
